/* ---------- [KD] الشريط السفلي يلتصق بأسفل الشاشة الظاهرة: يقيس الفرق بين أسفل الشريط وأسفل الشاشة الظاهرة (visualViewport) ويزيحه به عبر --kBb ---------- */
(function(){
  var vv=window.visualViewport,m=document.querySelector('.mobMn'),root=document.documentElement;
  if(!vv||!m) return;
  var g=0,raf=0;
  function fix(){
    raf=0;
    if(vv.scale>1.01||getComputedStyle(m).display==='none') return;
    var bottom=m.getBoundingClientRect().bottom-g;
    var ng=Math.round(vv.offsetTop+vv.height-bottom);
    if(Math.abs(ng)<2) ng=0;
    if(ng>200||ng<-200) ng=0;
    if(ng!==g){ g=ng; root.style.setProperty('--kBb',g+'px'); }
  }
  function later(){ if(!raf) raf=requestAnimationFrame(fix); }
  vv.addEventListener('resize',later); vv.addEventListener('scroll',later);
  window.addEventListener('scroll',later,{passive:true}); window.addEventListener('resize',later);
  window.addEventListener('touchend',function(){setTimeout(later,350)},{passive:true});
  later();
})();
